import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";

const files = execSync('git grep -l disableTooltip -- src', { encoding: "utf8" })
    .split("\n").map(s => s.trim()).filter(Boolean);

const OLD = "disableTooltip", NEW = "hideHint";
let counts = { tag: 0, ref: 0, ts: 0, css: 0 };

// rename the attribute/binding name of OLD inside the opening tag of the given elements
function renameInTags(text, tagNames) {
    const re = new RegExp(`<(${tagNames.join("|")})(\\s[^<>]*?)?(/?>)`, "g");
    return text.replace(re, (m) => {
        const out = m
            .replace(new RegExp(`\\[${OLD}\\]`, "g"), `[${NEW}]`)
            .replace(new RegExp(`(^|\\s)${OLD}(?=(\\s|=|/|>))`, "g"), (mm, p1) => {
                return p1 + NEW;
            });
        if (out !== m) counts.tag++;
        return out;
    });
}

for (const f of files) {
    const before = readFileSync(f, "utf8");
    let t = before;

    if (f.endsWith(".css")) {
        t = t.replace(/(app-pill|app-fancy-pill|app-status-pill)\[disableTooltip\]/g, (m, tag) => {
            counts.css++;
            return `${tag}[${NEW}]`;
        });
    } else {
        // (2) template bindings on the subclasses
        t = renameInTags(t, ["app-fancy-pill", "app-status-pill"]);
        // (3) template reads through the #fancyRef template reference (an <app-fancy-pill>)
        t = t.replace(/\bfancyRef\.disableTooltip\b/g, () => { counts.ref++; return `fancyRef.${NEW}`; });
        // (3) TypeScript reads through queries typed PillComponent / FancyPillComponent
        t = t.replace(/\b(pill|fancy)\.disableTooltip\b/g, (m, r) => { counts.ts++; return `${r}.${NEW}`; });
        t = t.replace(/\b(fancy|firstPill)\(\)(\??)\.disableTooltip\b/g, (m, r, q) => { counts.ts++; return `${r}()${q}.${NEW}`; });
    }

    if (t !== before) writeFileSync(f, t);
}

console.log(counts);

